/**
 * R7 decision D7 on the chain: the authority budget (rail/authority.ts) of one workspace's treasury vault, read from
 * the release's own events, and what a payment or a conversion would cost against it. The co-signer's fork uses it
 * for check C12 when its configuration says `authority: "d7"` (rail/cosigner-engine.ts, generated by
 * scripts/fork-cosigner.mjs); the rail's payment preview asks the co-signer for the same figures (rail/treasury.ts),
 * so preview and enforcement are one computation. Spec: experiments/r7/S1-science/D7-authority-budget.md.
 *
 * Which events of the release's contracts are which events of the rule:
 *   QEDVault.PaymentExecuted, liability 0, to an execution module: a conversion. Its QEDExecution.BestExecution (same
 *        intent, same transaction, emitted by that module) says what was spent and what reached whom. Output to C:
 *        B −= ⌈max(0, spent·1 − out·lo)⌉ at the reference band of the output asset (no band: the output is worth 0).
 *        Output elsewhere, or no matching BestExecution: a payment of the input. The unspent rest that the module
 *        returns to the vault is a receipt into C: nothing.
 *   PaymentExecuted, liability 0, to an address in C: a self-payment, nothing. To anyone else: B −= amount (the vault's
 *        own asset is the numeraire, lo = mid = hi = 1).
 *   PaymentExecuted with liability n > 0: the agent's forward payment, ring-fenced for its creditor: a hold, A −= amount
 *        (to C: a self-payment). Its LiabilitySettled: to C, A += amount; to anyone else, B −= amount. Its
 *        LiabilityReleased: A += amount. A liability the OWNER ring-fenced is the owner's own act and is not counted.
 *   ProofEscrow.JobSettled to an address in C: a credit of ⌊r·price⌋ when the job's client (its JobOpened) is outside
 *        P, it was paid in the vault's own asset, and the settlement has k confirmations; otherwise a receipt that is
 *        not earnings. Credits in other assets are not given (spec section 8, item 3).
 *   Withdrawn, Deposited, the owner's ringFence, anything else: not counted (owner actions and receipts).
 *   ERC-20 Transfer of the vault's asset from an address of C to an address outside C (a payment, a promise paid, an
 *        owner's withdrawal, the owner account's own transfer): money the workspace sent that address. K1
 *        (rail/earned-authority.ts) sets it against that address's later settlements, so that money sent out and paid
 *        straight back is not earnings, and caps what is earned in any window of chain time, in all and per payer.
 * Owner grants come from the co-signer's durable state: owner-signed messages it verified with the owner account
 * (ERC-1271). Certificates the co-signer signed and the chain has not used yet are reserved at their worst case until
 * they are used, expire, or the vault's epoch voids them, so that two certificates cannot both spend the same room.
 *
 * The budget is recomputed from the chain's history every time (facts mode: what happened is applied as it happened).
 * A settlement that a restored or reorganised chain no longer holds is simply not credited, which is the rule's
 * "uncredit"; no event on this chain links value back to a debit, so the rule's reversal does not occur here.
 */
import type { Address, Hex } from "viem";
import type { AuthorityView } from "../types.ts";
// the rules come through the verification kernel's one entry point (K2; apps/qed-demo/KERNEL.md); this module is the
// co-signer's adapter: it turns the release's events into the rules' events
import { AuthorityBudget, NUMERAIRE, UNVALUED, addQ, band, ceilQ, checkEarnedCap as checkCap, defaultEarnedCap, EarnedLedger, floorQ, parseQ, q, scaleQ, subQ, type Band, type EarnedCap, type EarnedCredit, type Q } from "../../shared/kernel/index.ts";

/** A reference band for one asset, in numeraire base units per asset base unit ("n/d" strings), and where it comes from. */
export interface Reference {
  token: Address;
  symbol: string;
  decimals: number;
  lo: string;
  mid: string;
  hi: string;
  /** A conversion is admitted only while the venues' depth-weighted mid lies inside [lo·(1 − δ), hi·(1 + δ)]; δ in basis points. */
  divergenceBps: number;
  /** In words: what supplies this band, and why it cannot be moved by the agent's trades. */
  source: string;
}

/** Everything the co-signer needs to apply D7 to one treasury vault. Plain JSON, so it crosses the co-signer's process boundary. */
export interface D7Config {
  vault: Address;
  /** The vault's own asset, the numeraire of the budget. */
  asset: Address;
  symbol: string;
  decimals: number;
  /** The vault's execution module(s): a payment to one of them is the input of a conversion. */
  execution: Address[];
  /** The escrow whose settlements to the workspace may be earnings (null: none). */
  escrow: Address | null;
  /** B0 in base units of the vault's asset (owner-granted, unearned). */
  base: string;
  /** r, as "n/d"; theorem T3 needs r ≤ 1. */
  rate: string;
  /** k: a settlement counts once it has this many confirmations. */
  confirmations: number;
  /** C: payments to these consume nothing (the workspace's vaults and owner account). */
  control: Address[];
  /**
   * Which assets each address of C can release. A QEDVault transfers only its own asset (QEDVault.sol: executePayment,
   * settle and withdraw all move `asset`), so tINR sent to the tUSD reserve vault can never leave it: for tINR that
   * vault is not in C, and what reaches it is gone. Absent: every address of C releases every asset (the rule as
   * before; kept for configurations that predate this field). Present: an address of C without an entry is in C for
   * nothing (fail safe).
   */
  controlAssets?: { address: Address; assets: Address[] | "any" }[];
  /** P ⊇ C: receipts from these are never earnings (C, the service's keys of the workspace, its modules, linked workspaces). */
  principal: Address[];
  references: Reference[];
  /**
   * K1: the most earned authority in any window of chain time, from all payers together and from any one payer, in
   * base units of the vault's asset. Absent: 1,000 units in any 30 days and 250 from any one payer (DEFAULT_EARNED_CAP).
   */
  earnedCap?: { windowSeconds: number; perWindow: string; perPayer: string };
}

/** The earned-authority caps a configuration states, or the defaults in the asset's own units. */
export function earnedCapOf(cfg: Pick<D7Config, "earnedCap" | "decimals">): EarnedCap {
  if (!cfg.earnedCap) return defaultEarnedCap(cfg.decimals);
  return checkCap({ windowSeconds: cfg.earnedCap.windowSeconds, perWindow: BigInt(cfg.earnedCap.perWindow), perPayer: BigInt(cfg.earnedCap.perPayer) });
}

/**
 * D-K1b: the caps K1 applies: the operator's (the configuration, which stays the ceiling) lowered by the owner's
 * passkey-signed caps where those are lower; never raised by them. `owner` null, or a cap null: the operator's applies.
 */
export function withOwnerCaps(cfg: D7Config, owner: { perWindow: string | null; perPayer: string | null } | null | undefined): D7Config {
  if (!owner || (owner.perWindow === null && owner.perPayer === null)) return cfg;
  const op = earnedCapOf(cfg);
  const min = (a: bigint, b: string | null) => (b !== null && BigInt(b) < a ? BigInt(b) : a);
  return { ...cfg, earnedCap: { windowSeconds: op.windowSeconds, perWindow: min(op.perWindow, owner.perWindow).toString(), perPayer: min(op.perPayer, owner.perPayer).toString() } };
}

export interface Grant { nonce: string; amount: string; at: string }
export interface Reservation { intentId: Hex; cost: string; kind: "payment" | "hold" | "conversion"; expiresAt: string; epoch: string; at: string }

interface At { blockNumber: bigint; logIndex: number; transactionHash: Hex; address: Address; blockHash?: Hex | null; blockTimestamp?: bigint | null }
export type ChainEvent =
  | { type: "payment"; block: bigint; index: number; intentId: Hex; recipient: Address; amount: bigint; liabilityId: bigint; conversion: { tokenOut: Address; recipient: Address; spent: bigint; amountOut: bigint } | null }
  | { type: "liability-settled"; block: bigint; index: number; id: bigint; creditor: Address; amount: bigint }
  | { type: "liability-released"; block: bigint; index: number; id: bigint; amount: bigint }
  | { type: "job-settled"; block: bigint; index: number; jobId: bigint; payee: Address; price: bigint; client: Address | null; token: Address | null; time: bigint | null }
  | { type: "sent"; block: bigint; index: number; from: Address; to: Address; amount: bigint };

/** Decoded logs, as viem's getContractEvents returns them. */
export interface AuthorityLogs {
  payments: (At & { args: { intentId: Hex; recipient: Address; amount: bigint; liabilityId: bigint } })[];
  liabilitySettled: (At & { args: { id: bigint; creditor: Address; amount: bigint; settledBy?: Address } })[];
  liabilityReleased: (At & { args: { id: bigint; amount: bigint; creditor?: Address } })[];
  executions: (At & { args: { intentId: Hex; tokenOut: Address; recipient: Address; amountIn: bigint; spent: bigint; amountOut: bigint } })[];
  jobsOpened: (At & { args: { jobId: bigint; client: Address; payee: Address; token: Address; price: bigint } })[];
  jobsSettled: (At & { args: { jobId: bigint; payee: Address; price: bigint } })[];
  /** Transfers of the vault's asset out of the addresses of C (absent: none read). */
  transfers?: (At & { args: { from: Address; to: Address; value: bigint } })[];
}

/** The ERC-20 Transfer event, the only part of a token's interface the ledger reads. */
export const TRANSFER_EVENT_ABI = [{ type: "event", name: "Transfer", inputs: [{ name: "from", type: "address", indexed: true }, { name: "to", type: "address", indexed: true }, { name: "value", type: "uint256", indexed: false }] }] as const;
/** Block times by block hash: a block's time never changes, and a hash names one block. */
const blockTimes = new Map<string, bigint>();

const low = (x: string) => x.toLowerCase();

/** Whether value of `token` at `addr` is under the workspace's control: `addr` is in C and can release `token`. */
export function inControl(cfg: D7Config, addr: Address, token: Address): boolean {
  if (!cfg.control.some((c) => low(c) === low(addr))) return false;
  if (!cfg.controlAssets) return true;
  const e = cfg.controlAssets.find((x) => low(x.address) === low(addr));
  return !!e && (e.assets === "any" || e.assets.some((t) => low(t) === low(token)));
}
/**
 * The address as the rule should see it for `token`: itself when it is in C for that asset or outside C, and a key
 * that is in neither C nor P when it is in C but cannot release the asset (the value is locked there: for the
 * workspace it has left, and no one else can take it).
 */
const ruleKey = (cfg: D7Config, addr: Address, token: Address) => (inControl(cfg, addr, token) || !cfg.control.some((c) => low(c) === low(addr)) ? low(addr) : `${low(addr)}#cannot-release:${low(token)}`);

/** Reads the vault's, its execution modules' and the escrow's events since `fromBlock`. */
export async function readAuthorityLogs(pub: any, cfg: D7Config, abi: { vault: unknown; execution: unknown; escrow: unknown }, fromBlock: bigint): Promise<{ logs: AuthorityLogs; latestBlock: bigint }> {
  const ev = (address: Address, a: unknown, eventName: string) => pub.getContractEvents({ address, abi: a, eventName, fromBlock }) as Promise<any[]>;
  const [latestBlock, payments, liabilitySettled, liabilityReleased, executions, jobsOpened, jobsSettled, transfers] = await Promise.all([
    // never viem's cached block number (it can be seconds old): confirmations are counted from the chain's latest block
    pub.getBlockNumber({ cacheTime: 0 }) as Promise<bigint>,
    ev(cfg.vault, abi.vault, "PaymentExecuted"),
    ev(cfg.vault, abi.vault, "LiabilitySettled"),
    ev(cfg.vault, abi.vault, "LiabilityReleased"),
    Promise.all(cfg.execution.map((x) => ev(x, abi.execution, "BestExecution"))).then((xs) => xs.flat()),
    cfg.escrow ? ev(cfg.escrow, abi.escrow, "JobOpened") : Promise.resolve([]),
    cfg.escrow ? ev(cfg.escrow, abi.escrow, "JobSettled") : Promise.resolve([]),
    // K1: every transfer of the vault's asset out of an address of C (the topic filter takes any of them)
    pub.getContractEvents({ address: cfg.asset, abi: TRANSFER_EVENT_ABI, eventName: "Transfer", args: { from: cfg.control }, fromBlock }) as Promise<any[]>,
  ]);
  // K1 counts a settlement at its block's time; a node that does not put the time in its logs is asked for the block
  for (const s of jobsSettled) {
    if (typeof s.blockTimestamp === "bigint") continue;
    const key = String(s.blockHash ?? "").toLowerCase();
    let t = key ? blockTimes.get(key) : undefined;
    if (t === undefined) {
      const b = await pub.getBlock(s.blockHash ? { blockHash: s.blockHash } : { blockNumber: s.blockNumber });
      t = BigInt(b.timestamp);
      if (key) { if (blockTimes.size > 50_000) blockTimes.clear(); blockTimes.set(key, t); }
    }
    s.blockTimestamp = t;
  }
  return { logs: { payments, liabilitySettled, liabilityReleased, executions, jobsOpened, jobsSettled, transfers }, latestBlock };
}

/** The logs as the rule's events, in chain order. Conversions are matched to their execution by intent, module and transaction. */
export function eventsFromLogs(cfg: D7Config, logs: AuthorityLogs): ChainEvent[] {
  const modules = new Set(cfg.execution.map(low));
  const execs = new Map<string, AuthorityLogs["executions"][number]>();
  for (const e of logs.executions) execs.set(`${low(e.address)}:${low(e.transactionHash)}:${low(e.args.intentId)}`, e);
  const opened = new Map<string, AuthorityLogs["jobsOpened"][number]>();
  for (const o of logs.jobsOpened) opened.set(o.args.jobId.toString(), o);
  const out: ChainEvent[] = [];
  for (const p of logs.payments) {
    const isModule = modules.has(low(p.args.recipient)) && p.args.liabilityId === 0n;
    const x = isModule ? execs.get(`${low(p.args.recipient)}:${low(p.transactionHash)}:${low(p.args.intentId)}`) : undefined;
    out.push({ type: "payment", block: p.blockNumber, index: p.logIndex, intentId: p.args.intentId, recipient: p.args.recipient, amount: p.args.amount, liabilityId: p.args.liabilityId, conversion: x ? { tokenOut: x.args.tokenOut, recipient: x.args.recipient, spent: x.args.spent, amountOut: x.args.amountOut } : null });
  }
  for (const s of logs.liabilitySettled) out.push({ type: "liability-settled", block: s.blockNumber, index: s.logIndex, id: s.args.id, creditor: s.args.creditor, amount: s.args.amount });
  for (const r of logs.liabilityReleased) out.push({ type: "liability-released", block: r.blockNumber, index: r.logIndex, id: r.args.id, amount: r.args.amount });
  for (const j of logs.jobsSettled) {
    const o = opened.get(j.args.jobId.toString());
    out.push({ type: "job-settled", block: j.blockNumber, index: j.logIndex, jobId: j.args.jobId, payee: j.args.payee, price: j.args.price, client: o ? o.args.client : null, token: o ? o.args.token : null, time: typeof j.blockTimestamp === "bigint" ? j.blockTimestamp : null });
  }
  // K1: what left C for an address outside it (a transfer between addresses of C stays in the workspace)
  const C = new Set(cfg.control.map(low));
  for (const t of logs.transfers ?? []) if (C.has(low(t.args.from)) && !C.has(low(t.args.to)) && low(t.address) === low(cfg.asset)) out.push({ type: "sent", block: t.blockNumber, index: t.logIndex, from: t.args.from, to: t.args.to, amount: t.args.value });
  return out.sort((a, b) => (a.block === b.block ? a.index - b.index : a.block < b.block ? -1 : 1));
}

/** The reference of an asset as a band; the vault's own asset is exact. */
export function bandOf(cfg: D7Config, token: Address): { band: Band; ref: Reference | null } {
  if (low(token) === low(cfg.asset)) return { band: NUMERAIRE, ref: null };
  const ref = cfg.references.find((r) => low(r.token) === low(token)) ?? null;
  return { band: ref ? band(parseQ(ref.lo), parseQ(ref.mid), parseQ(ref.hi)) : UNVALUED, ref };
}

export interface Ledger {
  rule: AuthorityBudget;
  base: bigint;
  grants: bigint;
  earned: bigint;
  consumed: { payments: bigint; conversions: bigint; promisesPaid: bigint; total: bigint };
  held: bigint;
  reserved: bigint;
  budget: bigint;
  /** What admission uses: the rule's availability less what outstanding certificates reserve. May be negative. */
  available: bigint;
  pendingCredits: { jobId: string; price: bigint; confirmations: number }[];
  notEarnings: { jobId: string; why: string }[];
  liveReservations: Reservation[];
  /** K1: the caps, every final settlement's credit with what netting and the caps kept from it, and what was earned in the window ending now. */
  earnedCap: EarnedCap;
  earnedCredits: EarnedCredit[];
  earnedInWindow: bigint;
}

/** Replays the chain's history (and the co-signer's grants and reservations) into the rule, in facts mode. */
export function buildLedger(cfg: D7Config, events: ChainEvent[], o: { latestBlock: bigint; grants: Grant[]; reservations: Reservation[]; now: bigint; epoch: bigint }): Ledger {
  const C = new Set(cfg.control.map(low)), P = new Set([...cfg.principal, ...cfg.control].map(low));
  const rule = new AuthorityBudget({ base: BigInt(cfg.base), rate: parseQ(cfg.rate), confirmations: cfg.confirmations }, C, P, { facts: true });
  for (const g of o.grants) rule.grant(`grant:${g.nonce}`, BigInt(g.amount));
  const holds = new Map<string, string>(); // liability id → hold id
  const executed = new Set<string>();
  const pendingCredits: Ledger["pendingCredits"] = [], notEarnings: Ledger["notEarnings"] = [];
  const consumed = { payments: 0n, conversions: 0n, promisesPaid: 0n, total: 0n };
  const earnedCap = earnedCapOf(cfg), k1 = new EarnedLedger(earnedCap, parseQ(cfg.rate));
  for (const e of events) {
    if (e.type === "sent") { k1.sent(low(e.to), e.amount); continue; }
    if (e.type === "payment") {
      executed.add(low(e.intentId));
      const to = ruleKey(cfg, e.recipient, cfg.asset);
      if (e.liabilityId > 0n) {
        if (C.has(to)) rule.pay(e.intentId, to, e.amount);
        else { const id = `liability:${e.liabilityId}`; rule.hold(id, e.amount, to); holds.set(e.liabilityId.toString(), id); }
      } else if (e.conversion) {
        const d = rule.convert(e.intentId, e.conversion.spent, NUMERAIRE, e.conversion.amountOut, bandOf(cfg, e.conversion.tokenOut).band, ruleKey(cfg, e.conversion.recipient, e.conversion.tokenOut));
        // a conversion whose output left the workspace is a payment of its input
        if (rule.log.at(-1)?.kind === "convert") consumed.conversions -= d; else consumed.payments -= d;
      } else consumed.payments -= rule.pay(e.intentId, to, e.amount);
    } else if (e.type === "liability-settled") {
      const id = holds.get(e.id.toString());
      if (id && rule.holds.has(id)) {
        const before = rule.budget;
        rule.settleHold(id, ruleKey(cfg, e.creditor, cfg.asset));
        consumed.promisesPaid += before - rule.budget;
      }
    } else if (e.type === "liability-released") {
      const id = holds.get(e.id.toString());
      if (id && rule.holds.has(id)) rule.releaseHold(id);
    } else if (C.has(low(e.payee))) {
      const jobId = `job:${e.jobId}`;
      const confirmations = Number(o.latestBlock - e.block + 1n);
      if (e.client === null || e.token === null) { notEarnings.push({ jobId, why: "the job's opening is not on this chain, so its client cannot be shown to be outside the workspace" }); continue; }
      if (!inControl(cfg, e.payee, e.token)) { notEarnings.push({ jobId, why: `paid into ${e.payee}, an account of the workspace that cannot release ${bandOf(cfg, e.token).ref?.symbol ?? (low(e.token) === low(cfg.asset) ? cfg.symbol : e.token)}: the money is locked there, so it is not earnings` }); continue; }
      if (P.has(low(e.client))) { notEarnings.push({ jobId, why: "its client is in the workspace's principal set (the workspace's own account, a key of its service, or a workspace sharing a member): self-dealt, not earnings" }); rule.credit(jobId, low(e.client), low(e.payee), e.price, NUMERAIRE, confirmations); continue; }
      if (low(e.token) !== low(cfg.asset)) { notEarnings.push({ jobId, why: `paid in ${bandOf(cfg, e.token).ref?.symbol ?? e.token}, not in ${cfg.symbol}: only the vault's own asset is credited` }); continue; }
      if (confirmations < cfg.confirmations || rule.credited.has(jobId)) {
        if (confirmations < cfg.confirmations) pendingCredits.push({ jobId, price: e.price, confirmations });
        rule.credit(jobId, low(e.client), low(e.payee), e.price, NUMERAIRE, confirmations);
        continue;
      }
      // final: K1 nets what the workspace sent this client and applies the caps; D7's credit is never raised
      const k = k1.credit(jobId, low(e.client), e.price, e.time);
      rule.credit(jobId, low(e.client), low(e.payee), e.price, NUMERAIRE, confirmations, k.credit);
    }
  }
  let grants = 0n, earned = 0n;
  for (const x of rule.log) { if (x.kind === "grant") grants += x.deltaBudget; if (x.kind === "credit") earned += x.deltaBudget; }
  consumed.total = consumed.payments + consumed.conversions + consumed.promisesPaid;
  const liveReservations = o.reservations.filter((r) => !executed.has(low(r.intentId)) && BigInt(r.expiresAt) >= o.now && BigInt(r.epoch) === o.epoch);
  const reserved = liveReservations.reduce((s, r) => s + BigInt(r.cost), 0n);
  let held = 0n;
  for (const h of rule.holds.values()) held += h.amount;
  return { rule, base: BigInt(cfg.base), grants, earned, consumed, held, reserved, budget: rule.budget, available: rule.available - reserved, pendingCredits, notEarnings, liveReservations, earnedCap, earnedCredits: k1.credits, earnedInWindow: k1.inWindowAt(o.now) };
}

// ───────────── admission: what an action would cost ─────────────

/** A payment of the vault's own asset: to C nothing; to anyone else its amount; a forward payment holds its amount. */
export function paymentCost(cfg: D7Config, recipient: Address, amount: bigint, forward: boolean): { cost: bigint; how: "self-payment" | "payment" | "hold" } {
  if (inControl(cfg, recipient, cfg.asset)) return { cost: 0n, how: "self-payment" };
  return { cost: amount, how: forward ? "hold" : "payment" };
}

/**
 * The worst case of a conversion before it executes: the chain refuses any output below the order's floor, so its
 * realised cost is at most ⌈max(0, amountIn·hi_in − minOut·lo_out)⌉. `marketOutPerIn` is the venues' depth-weighted mid
 * (output base units per input base unit, the release's T2 figure); outside the reference band widened by its
 * divergence, the reference does not describe the market and the conversion is refused (`inside: false`).
 */
export function conversionCost(cfg: D7Config, o: { tokenIn: Address; amountIn: bigint; tokenOut: Address; minOut: bigint; recipient: Address; marketOutPerIn: number }): { cost: bigint; how: "conversion" | "convert-and-pay" | "unvalued" | "unvalued-input"; ref: Reference | null; market: number | null; inside: boolean } {
  const inRef = bandOf(cfg, o.tokenIn), outB = bandOf(cfg, o.tokenOut);
  // what leaves must be valued at the top of its band: an input with no reference cannot be, so it is refused, never free
  if (low(o.tokenIn) !== low(cfg.asset) && !inRef.ref) return { cost: 0n, how: "unvalued-input", ref: null, market: null, inside: false };
  const inB = inRef.band;
  const input = ceilQ(scaleQ(o.amountIn, inB.hi));
  if (!inControl(cfg, o.recipient, o.tokenOut)) return { cost: input, how: "convert-and-pay", ref: outB.ref, market: null, inside: true };
  if (!outB.ref) return { cost: input, how: "unvalued", ref: null, market: null, inside: true };
  const market = o.marketOutPerIn > 0 && Number.isFinite(o.marketOutPerIn) ? 1 / o.marketOutPerIn : null;
  const d = outB.ref.divergenceBps / 10_000;
  const inside = market !== null && market >= qNum(outB.band.lo) * (1 - d) && market <= qNum(outB.band.hi) * (1 + d);
  const cost = subQ(scaleQ(o.amountIn, inB.hi), scaleQ(o.minOut, outB.band.lo));
  return { cost: ceilQ(cost.n < 0n ? q(0n) : cost), how: "conversion", ref: outB.ref, market, inside };
}
const qNum = (x: Q) => Number(x.n) / Number(x.d);

// ───────────── words and figures ─────────────

/** An exact amount in an asset's own units: "1,250.50" is never produced (no grouping), "-3.08" can be. */
export function units(x: bigint, decimals: number): string {
  const neg = x < 0n, s = (neg ? -x : x).toString().padStart(decimals + 1, "0");
  return `${neg ? "-" : ""}${decimals ? `${s.slice(0, -decimals)}.${s.slice(-decimals)}` : s}`;
}
/** A reference price in whole units of each asset: numeraire per one unit of the asset, to `places` decimals. */
export function price(x: Q, ref: Reference, cfg: D7Config, places = 4): string {
  const scaled = q(x.n * 10n ** BigInt(ref.decimals) * 10n ** BigInt(places), x.d * 10n ** BigInt(cfg.decimals));
  return units(floorQ(addQ(scaled, q(1n, 2n))), places).replace(/\.?0+$/, "");
}

/** A window of chain time in words: "30 days", "12 hours", "90 seconds". */
export function windowWords(seconds: number): string {
  const [n, unit] = seconds % 86_400 === 0 ? [seconds / 86_400, "day"] : seconds % 3_600 === 0 ? [seconds / 3_600, "hour"] : [seconds, "second"];
  return `${n} ${unit}${n === 1 ? "" : "s"}`;
}

/** K1's cap in one sentence, as every place that shows the earned figure states it. */
export function earnedCapWords(cfg: D7Config, cap: EarnedCap): string {
  const u = (x: bigint) => units(x, cfg.decimals), S = cfg.symbol;
  return `earned authority counts at most ${u(cap.perWindow)} ${S} in any ${windowWords(cap.windowSeconds)}, at most ${u(cap.perPayer)} ${S} from any one payer, and nothing of what this workspace had sent the payer first`;
}

/** The figures in the vault asset's units, and one plain sentence that adds them up. */
export function viewOf(cfg: D7Config, l: Ledger): AuthorityView {
  const u = (x: bigint) => units(x, cfg.decimals), S = cfg.symbol;
  const granted = l.base + l.grants;
  const netted = l.earnedCredits.reduce((s, c) => s + c.netted, 0n), heldBack = l.earnedCredits.reduce((s, c) => s + (c.uncapped - c.credit), 0n);
  const statement = `${u(l.available)} ${S} available = granted ${u(granted)} (base ${u(l.base)}, owner grants ${u(l.grants)}) + earned ${u(l.earned)} − used ${u(l.consumed.total)} (payments ${u(l.consumed.payments)}, conversion costs ${u(l.consumed.conversions)}, promises paid ${u(l.consumed.promisesPaid)}) − promised and not yet paid ${u(l.held)} − reserved for certificates not yet used ${u(l.reserved)}; ${earnedCapWords(cfg, l.earnedCap)} (${u(l.earnedInWindow)} ${S} earned in the last ${windowWords(l.earnedCap.windowSeconds)})`;
  return {
    rule: "d7", asset: { symbol: S, decimals: cfg.decimals },
    base: l.base.toString(), grants: l.grants.toString(), granted: granted.toString(), earned: l.earned.toString(),
    earnedLimit: { windowSeconds: l.earnedCap.windowSeconds, perWindow: l.earnedCap.perWindow.toString(), perPayer: l.earnedCap.perPayer.toString(), inWindow: l.earnedInWindow.toString(), netted: netted.toString(), heldBack: heldBack.toString() },
    used: l.consumed.total.toString(), usedBy: { payments: l.consumed.payments.toString(), conversions: l.consumed.conversions.toString(), promisesPaid: l.consumed.promisesPaid.toString() },
    held: l.held.toString(), reserved: l.reserved.toString(), budget: l.budget.toString(), available: l.available.toString(),
    rate: cfg.rate, confirmations: cfg.confirmations, pendingCredits: l.pendingCredits.length, notEarnings: l.notEarnings.length,
    references: cfg.references.map((r) => { const b = bandOf(cfg, r.token).band; return { symbol: r.symbol, lo: price(b.lo, r, cfg), mid: price(b.mid, r, cfg), hi: price(b.hi, r, cfg), divergenceBps: r.divergenceBps, source: r.source }; }),
    statement,
    limits: [
      `Earned means paid for, through the escrow, by a client this workspace does not know to be its own, counted once the payment is final; ${earnedCapWords(cfg, l.earnedCap)}. A client the wallet has never seen cannot be told apart from an unregistered address of a member, and two people paying each other real money cannot be told apart from trade by any rule that reads only the chain: the cap is what bounds both (D7 assumption A-ID; a second workspace counts as the workspace's own only when it shares a member's passkey).`,
      `Conversions count only their cost against a fixed reference band, so the mandate's own limits on amounts per payment, per period and over its life are what bound how much can be converted.`,
    ],
  };
}
